import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import MenuIcon from '@mui/icons-material/Menu';
import CloseIcon from '@mui/icons-material/Close';
import logo from '../assets/logo.png';
import './Navbar.css';

const navLinks = [
    { path: '/', label: 'Home' },
    { path: '/staff', label: 'Staff' },
    { path: '/gallery', label: 'Gallery' },
    { path: '/admission', label: 'Admission' },
    { path: '/contact', label: 'Contact' },
];

export default function Navbar() {
    const [scrolled, setScrolled] = useState(false);
    const [mobileOpen, setMobileOpen] = useState(false);
    const location = useLocation();

    useEffect(() => {
        const onScroll = () => setScrolled(window.scrollY > 50);
        window.addEventListener('scroll', onScroll);
        return () => window.removeEventListener('scroll', onScroll);
    }, []);

    useEffect(() => {
        setMobileOpen(false);
    }, [location]);

    return (
        <motion.nav
            className={`navbar ${scrolled ? 'navbar--scrolled' : ''}`}
            initial={{ y: -100 }}
            animate={{ y: 0 }}
            transition={{ duration: 0.6, ease: 'easeOut' }}
        >
            <div className="navbar__container">
                <Link to="/" className="navbar__brand">
                    <motion.img
                        src={logo}
                        alt="Sri Karthikeya Logo"
                        className="navbar__logo-img"
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        whileHover={{ scale: 1.05 }}
                        transition={{ duration: 0.5 }}
                    />
                    <motion.span
                        className="navbar__brand-text"
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ duration: 0.6, delay: 0.2 }}
                    >
                        Sri Karthikeya Tution Hub
                    </motion.span>
                </Link>

                {/* Desktop Nav */}
                <ul className="navbar__links">
                    {navLinks.map((link) => (
                        <li key={link.path}>
                            <Link
                                to={link.path}
                                className={`navbar__link ${location.pathname === link.path ? 'navbar__link--active' : ''}`}
                            >
                                {link.label}
                                {location.pathname === link.path && (
                                    <motion.div className="navbar__link-underline" layoutId="underline" />
                                )}
                            </Link>
                        </li>
                    ))}
                </ul>

                <Link to="/admission" className="navbar__cta ripple-button">
                    Enroll Now
                </Link>

                {/* Mobile Toggle */}
                <button className="navbar__toggle" onClick={() => setMobileOpen(!mobileOpen)}>
                    {mobileOpen ? (
                        <CloseIcon sx={{ fontSize: 28, color: (scrolled || mobileOpen) ? '#1a56db' : '#fff' }} />
                    ) : (
                        <MenuIcon sx={{ fontSize: 28, color: scrolled ? '#1a56db' : '#fff' }} />
                    )}
                </button>
            </div>

            {/* Mobile Menu */}
            <AnimatePresence>
                {mobileOpen && (
                    <motion.div
                        className="navbar__mobile"
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3 }}
                    >
                        {navLinks.map((link, i) => (
                            <motion.div
                                key={link.path}
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: i * 0.1 }}
                            >
                                <Link
                                    to={link.path}
                                    className={`navbar__mobile-link ${location.pathname === link.path ? 'navbar__mobile-link--active' : ''}`}
                                >
                                    {link.label}
                                </Link>
                            </motion.div>
                        ))}
                        <Link to="/admission" className="navbar__mobile-cta ripple-button">
                            Enroll Now
                        </Link>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.nav>
    );
}

import React from 'react';
import { motion } from 'framer-motion';

const pageVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0, transition: { duration: 0.5, ease: 'easeOut' } },
    exit: { opacity: 0, y: -20, transition: { duration: 0.3 } },
};

export default function PageTransition({ children }) {
    return (
        <motion.div
            variants={pageVariants}
            initial="initial"
            animate="animate"
            exit="exit"
        >
            {children}
        </motion.div>
    );
}

import React from 'react';
import { motion, useScroll, useSpring } from 'framer-motion';

export default function ScrollProgress() {
    const { scrollYProgress } = useScroll();
    const scaleX = useSpring(scrollYProgress, {
        stiffness: 100,
        damping: 30,
        restDelta: 0.001
    });

    return (
        <motion.div
            className="scroll-progress-bar"
            style={{
                scaleX,
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                height: '4px',
                background: 'linear-gradient(90deg, #1a56db, #d4a843)',
                transformOrigin: '0%',
                zIndex: 9999
            }}
        />
    );
}

import React from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';

export default function ScrollReveal({
    children,
    direction = 'up',
    delay = 0,
    duration = 0.6,
    once = true,
    className = '',
}) {
    const [ref, inView] = useInView({ triggerOnce: once, threshold: 0.15 });

    const variants = {
        hidden: {
            opacity: 0,
            y: direction === 'up' ? 40 : direction === 'down' ? -40 : 0,
            x: direction === 'left' ? 40 : direction === 'right' ? -40 : 0,
            scale: direction === 'scale' ? 0.9 : 1,
        },
        visible: {
            opacity: 1,
            y: 0,
            x: 0,
            scale: 1,
            transition: {
                duration,
                delay,
                ease: [0.25, 0.46, 0.45, 0.94],
            },
        },
    };

    return (
        <motion.div
            ref={ref}
            className={className}
            variants={variants}
            initial="hidden"
            animate={inView ? 'visible' : 'hidden'}
        >
            {children}
        </motion.div>
    );
}

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import PhoneIcon from '@mui/icons-material/Phone';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import EmailIcon from '@mui/icons-material/Email';
import './StaffCard.css';

const StaffCard = ({ id, name, subjects, shortExpertise, photo, mobile, whatsapp, email, delay }) => {
    const [isFlipped, setIsFlipped] = useState(false);

    return (
        <motion.div
            className="staff-card-v3-container"
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay }}
            onMouseEnter={() => setIsFlipped(true)}
            onMouseLeave={() => setIsFlipped(false)}
        >
            <div className={`flip-card-inner ${isFlipped ? 'is-flipped' : ''}`}>
                {/* Front Side */}
                <div className="flip-card-front glass-morphism">
                    <div className="card-top-gradient"></div>
                    <div className="photo-wrapper">
                        <div className="photo-circle-outer">
                            {photo ? (
                                <img src={photo} alt={name} className="staff-photo-img" />
                            ) : (
                                <div className="photo-placeholder-v3">{name.charAt(0)}</div>
                            )}
                        </div>
                        <div className="photo-glow-ring"></div>
                    </div>

                    <div className="card-info-front">
                        <h3 className="staff-name-v3">{name}</h3>
                        <p className="staff-expertise-v3">{shortExpertise}</p>
                        <div className="hover-hint">Hover to flip</div>
                    </div>

                    <div className="glow-border-v3"></div>
                </div>

                {/* Back Side */}
                <div className="flip-card-back glass-morphism">
                    <h3 className="back-name">{name}</h3>
                    <div className="subjects-list-v3">
                        <p className="subjects-title">Expertise:</p>
                        <div className="subjects-tags">
                            {subjects.slice(0, 4).map((sub, i) => (
                                <span key={i} className="back-subject-tag">{sub}</span>
                            ))}
                            {subjects.length > 4 && <span>+ more</span>}
                        </div>
                    </div>

                    <div className="contact-links-mini">
                        <div className="contact-item-mini">
                            <PhoneIcon sx={{ fontSize: 18 }} />
                            <span>{mobile}</span>
                        </div>
                        <div className="contact-item-mini">
                            <WhatsAppIcon sx={{ fontSize: 18 }} />
                            <span>{whatsapp}</span>
                        </div>
                        <div className="contact-item-mini">
                            <EmailIcon sx={{ fontSize: 18 }} />
                            <span className="email-text">{email}</span>
                        </div>
                    </div>

                    <Link to={`/staff/${id}`} className="full-profile-btn ripple-button">
                        View Full Profile <ArrowForwardIcon sx={{ fontSize: 16 }} />
                    </Link>
                </div>
            </div>
        </motion.div>
    );
};

export default StaffCard;

import React from 'react';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import { motion } from 'framer-motion';

