                                    <input
                                        type="text"
                                        name="parentName"
                                        required
                                        value={formData.parentName}
                                        onChange={handleChange}
                                        onFocus={() => setFocusedField('parentName')}
                                        onBlur={() => setFocusedField(null)}
                                    />
                                    <div className="focus-line"></div>
                                </div>

                                {/* Class */}
