                                        initial={{ opacity: 0, scale: 0.8 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        transition={{ type: 'spring' }}
                                    >
                                        <CheckCircleIcon sx={{ fontSize: 64, color: '#22c55e' }} />
                                        <h3>Message Sent!</h3>
                                        <p>We'll get back to you shortly.</p>
